 (SELECT COUNT(*) FROM sys.triggers g WHERE g.parent_id=t.object_id) AS triggers,
 OBJECT_ID(N'app.stock_movements_round22_history') AS proposed_history_id
 FROM sys.tables t WHERE t.object_id=OBJECT_ID(N'app.stock_movements_round_two_20261003');
