 FROM sys.columns c WHERE c.object_id=OBJECT_ID(N'app.stock_movements_round_two_20261003') ORDER BY c.column_id;
SELECT COUNT_BIG(*) AS row_count,SUM(CONVERT(bigint,units)) AS units,MAX(CONVERT(bigint,source_row_version)) AS newest_version
 FROM [app].[stock_movements_round_two_20261003];

